text:
#carddav-statusArea {
  background: transparent;
  border: 1px solid transparent;
  border-radius: 2px;
  padding: 3px 4px;
  color: var(--color-text-base);

  &[status="error"] {
    background-color: #ffe900;
    border-color: #f2d00f;
    color: var(--color-ink-90);
  }

  &[status="loading"] {
    background-color: rgba(0, 0, 0, 0.05);
    border-color: rgba(0, 0, 0, 0.1);
  }
}
